PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE produtos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sku TEXT,
  mlb TEXT NOT NULL UNIQUE,
  ean TEXT,
  nome TEXT NOT NULL,
  categoria TEXT,
  marca TEXT,
  peso_gramas INTEGER,
  altura_cm REAL,
  largura_cm REAL,
  comprimento_cm REAL,
  tipo_envio TEXT,
  status TEXT,
  atualizado_em TEXT DEFAULT (datetime('now'))
, loja_id TEXT, inventory_id TEXT);
CREATE TABLE estoque_historico (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  produto_id INTEGER NOT NULL,
  data_hora TEXT NOT NULL DEFAULT (datetime('now')),
  estoque_full INTEGER,
  estoque_empresa INTEGER,
  reservado INTEGER,
  em_transito INTEGER, loja_id TEXT,
  FOREIGN KEY (produto_id) REFERENCES produtos(id)
);
CREATE TABLE vendas (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  pedido_id TEXT NOT NULL,
  produto_id INTEGER NOT NULL,
  data_hora TEXT NOT NULL,
  quantidade INTEGER NOT NULL,
  valor_bruto REAL,
  comissao REAL,
  tarifa REAL,
  frete REAL,
  valor_liquido REAL, loja_id TEXT,
  UNIQUE(pedido_id, produto_id),
  FOREIGN KEY (produto_id) REFERENCES produtos(id)
);
CREATE TABLE envios (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  produto_id INTEGER NOT NULL,
  data TEXT NOT NULL,
  remessa TEXT,
  transportadora TEXT,
  quantidade_enviada INTEGER,
  valor_mercadoria REAL,
  valor_transporte REAL, loja_id TEXT,
  FOREIGN KEY (produto_id) REFERENCES produtos(id)
);
CREATE TABLE performance_historico (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  produto_id INTEGER NOT NULL,
  data TEXT NOT NULL,
  visualizacoes INTEGER,
  impressoes INTEGER,
  conversao REAL,
  posicao INTEGER, loja_id TEXT,
  FOREIGN KEY (produto_id) REFERENCES produtos(id)
);
CREATE TABLE eventos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tipo TEXT NOT NULL,
  data_hora TEXT NOT NULL DEFAULT (datetime('now')),
  produto_id INTEGER,
  payload_json TEXT,
  origem TEXT
, loja_id TEXT);
CREATE TABLE ml_auth (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  loja_id TEXT NOT NULL UNIQUE,
  access_token TEXT NOT NULL,
  refresh_token TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  atualizado_em TEXT DEFAULT (datetime('now'))
);
CREATE TABLE lojas (
  loja_id TEXT PRIMARY KEY,
  nickname TEXT,
  ativo INTEGER DEFAULT 1,
  criado_em TEXT DEFAULT (datetime('now'))
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_produtos_loja ON produtos(loja_id);
CREATE INDEX idx_vendas_loja ON vendas(loja_id);
CREATE INDEX idx_envios_loja ON envios(loja_id);
CREATE INDEX idx_estoque_loja ON estoque_historico(loja_id);
CREATE INDEX idx_performance_loja ON performance_historico(loja_id);
CREATE INDEX idx_eventos_loja ON eventos(loja_id);
CREATE UNIQUE INDEX ux_envios_loja_produto_remessa ON envios(loja_id, produto_id, remessa);
